import{_ as t,o as a,c as s,a5 as i}from"./chunks/framework.DGp912Ge.js";const g=JSON.parse('{"title":"Target Go — C++ Example","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/sdk/cpp/target-go.md","filePath":"software/sdk/cpp/target-go.md","lastUpdated":1783328958000}'),o={name:"software/sdk/cpp/target-go.md"};function r(d,e,n,l,h,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="target-go-—-c-example" tabindex="-1">Target Go — C++ Example <a class="header-anchor" href="#target-go-—-c-example" aria-label="Permalink to &quot;Target Go — C++ Example&quot;">​</a></h1><p><strong>Source</strong>: <code>rbq_sdk/cpp/example/src/rbq_target_go.cpp</code></p><p>A one-shot publisher that commands the robot to <strong>walk to a target pose</strong> (x, y, heading) with a chosen gait and approach mode. It publishes a single <code>TargetGo</code> message on <code>rt/rbq/cmd/target_go</code> and exits.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li>Reads <code>interface</code> and optional <code>x y theta gait mode</code> from the command line.</li><li>Initializes the DDS <code>ChannelFactory</code> on the given interface and creates a <code>Publisher&lt;TargetGo_&gt;</code> on <code>rt/rbq/cmd/target_go</code>.</li><li>Waits ~500 ms for DDS discovery, fills the <code>TargetGo</code> fields, publishes <strong>once</strong>, prints what it sent, and exits.</li></ol><p>The on-robot <strong>QuadWalk</strong> locomotion engine subscribes to <code>rt/rbq/cmd/target_go</code> and executes the walk.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>RBQ SDK built and installed — see <a href="/RBQ/software/sdk/cpp/overview.html">C++ SDK Overview</a>.</li><li>The robot stack running (simulator or hardware) and reachable on the same DDS interface.</li><li><strong>The robot must be powered on / in control and standing first.</strong> If you publish a target before control is started, QuadWalk rejects it with <code>Can&#39;t Receive cmd: CON_START first</code>.</li></ul><h2 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;Build&quot;">​</a></h2><p>From <code>rbq_sdk/cpp/example/</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/setup.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span></code></pre></div><p>Binary: <code>bin/rbq_target_go</code></p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_target_go</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">interfac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [x] [y] [theta_deg] [gait] [mode]</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># simulator, 1 m forward with wave gait:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_target_go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span></code></pre></div><p>Use the <strong>same interface as the running robot/sim</strong> (<code>lo</code> or your NIC). If discovery finds nothing, see the interface note on the <a href="/RBQ/software/sdk/cpp/image-echo.html">Image Echo</a> page (<code>lo</code> is often not multicast-capable; use a real NIC such as <code>enp3s0</code>).</p><p>Arguments (from the example&#39;s own usage):</p><table tabindex="0"><thead><tr><th>Arg</th><th>Meaning</th><th>Default</th></tr></thead><tbody><tr><td><code>interface</code></td><td>CycloneDDS interface (<code>lo</code> sim / NIC real)</td><td>required</td></tr><tr><td><code>x</code></td><td>target X (m), relative to start</td><td>1.0</td></tr><tr><td><code>y</code></td><td>target Y (m), relative to start</td><td>0.0</td></tr><tr><td><code>theta_deg</code></td><td>target heading</td><td>0.0</td></tr><tr><td><code>gait</code></td><td><code>0</code>=wave / <code>1</code>=stairs / <code>2</code>=RL</td><td>0</td></tr><tr><td><code>mode</code></td><td><code>0</code>=rot→straight→rot / <code>1</code>=rot→diag / <code>2</code>=diag→rot / <code>3</code>=rot+diag</td><td>0</td></tr></tbody></table><h2 id="example-output" tabindex="-1">Example output <a class="header-anchor" href="#example-output" aria-label="Permalink to &quot;Example output&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[rbq_target_go] published: gait=0 mode=0 x=1 y=0 theta=0</span></span></code></pre></div><p>The program publishes once and exits; the robot then walks to the target. Verified against the MuJoCo simulator — QuadWalk receives the command on <code>rt/rbq/cmd/target_go</code>; with the robot not yet in control it logs <code>Can&#39;t Receive cmd: CON_START first</code>, so start control (power on + stand) before sending a target.</p>`,20)])])}const k=t(o,[["render",r]]);export{g as __pageData,k as default};
